"use client";
/* eslint-disable @next/next/no-img-element -- Product images are served at their original local path. */
import {useEffect,useState} from "react";
import Link from "next/link";
import {memberRequest,useMember} from "./member-provider";
import {formatKRW} from "@/lib/format";
type Item={id:string;name:string;image:string;quantity:number;unitPrice:number;total:number;stock:number;available:boolean;kind:string};
export function CartView(){const {user,loading}=useMember();if(loading)return <p>장바구니를 확인하는 중입니다.</p>;if(!user)return <section className="member-card"><h1>로그인하고 장바구니를 이용하세요</h1><p>회원별로 상품과 수량을 안전하게 보관합니다.</p><Link href="/login">로그인하기 →</Link></section>;return <UserCart key={user.id}/>}
function UserCart(){const [data,setData]=useState<{items:Item[];total:number}|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState("");useEffect(()=>{let active=true;memberRequest("cart").then(d=>{if(active)setData(d)}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[]);
 async function change(body:unknown){setBusy(true);setError("");try{await memberRequest("cart",body);setData(await memberRequest("cart"))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <><p className="member-eyebrow">MY SHOPPING CART</p><h1>장바구니 <span>{data?.items.length??0}</span></h1>{error&&<p role="alert" className="member-error">{error}</p>}{!data?<p>상품을 불러오는 중입니다.</p>:!data.items.length?<section className="member-card"><h2>장바구니가 비어 있습니다</h2><p>상품 상세 화면에서 장바구니 버튼을 눌러 담아보세요.</p><Link href="/">부품 쇼핑하기 →</Link></section>:<div className="member-cart-layout"><section className="member-card"><div className="flex justify-between mb-5"><h2>담은 상품</h2><button disabled={busy} onClick={()=>{if(window.confirm("장바구니를 비우시겠습니까?"))void change({operation:"clear"})}}>전체 비우기</button></div>{data.items.map(item=><article className="member-cart-row" key={item.id}><img src={item.image||"/placeholders/case.svg"} alt={item.name}/><div className="flex-1"><small>{item.kind}</small><h3>{item.name}</h3><p>{formatKRW(item.unitPrice)}</p>{!item.available&&<p className="member-error">판매 중지 또는 재고 부족 · 합계에서 제외</p>}<div className="member-quantity"><button aria-label={`${item.name} 수량 줄이기`} disabled={busy||item.quantity<=1} onClick={()=>change({operation:"set",id:item.id,quantity:item.quantity-1})}>−</button><span>{item.quantity}</span><button aria-label={`${item.name} 수량 늘리기`} disabled={busy||item.quantity>=Math.min(99,item.stock)} onClick={()=>change({operation:"set",id:item.id,quantity:item.quantity+1})}>+</button><button disabled={busy} onClick={()=>change({operation:"remove",id:item.id})}>삭제</button></div></div><strong>{formatKRW(item.total)}</strong></article>)}</section><aside className="member-card member-cart-summary"><h2>상품 합계</h2><strong>{formatKRW(data.total)}</strong><p>현재 상품 가격과 할인율을 기준으로 계산합니다. 재고는 주문 시 다시 확인해야 합니다.</p><button className="member-primary" disabled>주문·결제 준비 중</button><Link href="/">쇼핑 계속하기</Link></aside></div>}</>;
}
